WITH enriched AS (SELECT *, COUNT(salary) OVER (PARTITION BY level, manager_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_salary, MIN(salary) OVER (PARTITION BY level, manager_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_salary, AVG(salary) OVER (PARTITION BY level, manager_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_salary FROM employees) SELECT s.id, s.dept_id, s.manager_id, s.job_title, s.hire_date, s.level, s.running_count_salary, s.running_min_salary, s.running_avg_salary, CASE WHEN job_title RLIKE '^(Analyst|Designer)$' THEN 'PRIORITY' ELSE 'GROUP_B' END AS job_title_zone, (SELECT MAX(t2.salary) FROM employees t2 WHERE t2.manager_id = s.manager_id) AS max_employee_salary FROM enriched s
